1	/**
2	 * Audit-log writer and reader. Subscribes to the whole event bus and records one row per domain event.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, toCsv
5	 */
6	import { toCsv } from "@/lib/csv";
7	import { subscribe } from "@/lib/event-bus";
8	import { isEnabled } from "@/lib/feature-flags";
9	import { assertCan } from "@/lib/permissions";
10	import { assertOrgScope } from "@/lib/tenant";
11	import * as activityRepo from "@/server/repositories/activity-repository";
12	import * as orgRepo from "@/server/repositories/organization-repository";
13	import { toIsoTimestamp } from "@/types/common";
14	import { activityResource } from "./_support";
15	import type { ActivityFilterInput, ExportActivityInput } from "@/schemas/activity";
16	import type {
17	  ActivityAction,
18	  ActivityEvent,
19	  ActivityGroup,
20	  ActivitySubjectKind,
21	} from "@/types/activity";
22	import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
23	import type { Unsubscribe } from "@/types/event";
24	import type { Actor } from "@/types/member";
25	
26	export type ActivityRecordInput = {
27	  actorId: UserId | null;
28	  subjectKind: ActivitySubjectKind;
29	  subjectId: string;
30	  projectId: ProjectId | null;
31	  summary: string;
32	  metadata?: Readonly<Record<string, string | number | boolean | null>>;
33	};
34	
35	/** Columns of the audit-log CSV export, in the order the file lists them. */
36	const EXPORT_COLUMNS = [
37	  "occurredAt",
38	  "action",
39	  "actorId",
40	  "subjectKind",
41	  "subjectId",
42	  "summary",
43	] as const;
44	
45	/**
46	 * Appends one audit row. Deliberately takes no `Actor`: the writer is usually
47	 * an event handler running outside a request, and the row's `actorId` comes
48	 * from the event payload rather than from an authenticated principal.
49	 */
50	export async function record(
51	  orgId: OrgId,
52	  action: ActivityAction,
53	  input: ActivityRecordInput,
54	): Promise<ActivityEvent> {
55	  return activityRepo.insertActivity({
56	    orgId,
57	    action,
58	    actorId: input.actorId,
59	    subjectKind: input.subjectKind,
60	    subjectId: input.subjectId,
61	    projectId: input.projectId,
62	    summary: input.summary,
63	    metadata: input.metadata ?? {},
64	    occurredAt: toIsoTimestamp(new Date()),
65	  });
66	}
67	
68	export async function listActivity(
69	  actor: Actor,
70	  input: ActivityFilterInput,
71	): Promise<Page<ActivityEvent>> {
72	  assertOrgScope(actor, input.orgId);
73	  assertCan(actor, "activity:read", activityResource(input.orgId));
74	  return activityRepo.listActivity(input);
75	}
76	
77	/** Groups a feed page by calendar day, newest day first. */
78	export function groupByDay(
79	  events: readonly ActivityEvent[],
80	): readonly ActivityGroup[] {
81	  const byDay = new Map<string, ActivityEvent[]>();
82	
83	  for (const event of events) {
84	    const day = event.occurredAt.slice(0, 10);
85	    const bucket = byDay.get(day) ?? [];
86	    bucket.push(event);
87	    byDay.set(day, bucket);
88	  }
89	
90	  return [...byDay.entries()]
91	    .sort(([a], [b]) => (a < b ? 1 : -1))
92	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
93	}
94	
95	/**
96	 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
97	 * for the role, and on the `csv_export` flag for the plan.
98	 */
99	export async function exportActivity(
100	  actor: Actor,
101	  input: ExportActivityInput,
102	): Promise<string> {
103	  assertOrgScope(actor, input.orgId);
104	  assertCan(actor, "activity:export", activityResource(input.orgId));
105	
106	  const org = await orgRepo.findOrgById(input.orgId);
107	  const flagEnabled = isEnabled("csv_export", {
108	    orgId: input.orgId,
109	    userId: actor.userId,
110	    plan: org?.plan ?? "free",
111	    role: actor.role,
112	    overrides: org?.settings.enabledFlagOverrides,
113	  });
114	
115	  if (input.format === "csv" && !flagEnabled) {
116	    throw new Error("CSV export is not included in this plan");
117	  }
118	
119	  const page = await activityRepo.listActivity({
120	    orgId: input.orgId,
121	    since: input.since,
122	    until: input.until,
123	    limit: 100,
124	    cursor: null,
125	  });
126	
127	  if (input.format === "json") {
128	    return JSON.stringify(page.items, null, 2);
129	  }
130	
131	  return toCsv(
132	    page.items.map((event) => ({
133	      occurredAt: event.occurredAt,
134	      action: event.action,
135	      actorId: event.actorId,
136	      subjectKind: event.subjectKind,
137	      subjectId: event.subjectId,
138	      summary: event.summary,
139	    })),
