/**
 * Copies every live issue of a project into another, for `ProjectService.cloneProject`.
 * Unlike `copyIssuesToProject`, this is a fresh start per ADR 0012: numbers run
 * from 1 in source order, status/assignee/dates reset, and the copy is authored
 * by the person cloning. Comments and attachments are never copied.
 */
export async function copyLiveIssuesForClone(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
  authorId: UserId,
): Promise<number> {
  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, fromProjectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number))
    .all();

  if (rows.length === 0) return 0;

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  const stamp = toIsoTimestamp(new Date());
  rows.forEach((row, index) => {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: index + 1,
        title: row.title,
        description: row.description,
        status: "backlog",
        priority: row.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: row.estimate,
        dueAt: row.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    const labelIds = (labels[row.id as IssueId] ?? []).map((l) => l.id);
    if (labelIds.length > 0) {
      db.insert(issueLabels)
        .values(labelIds.map((labelId) => ({ orgId, issueId: id, labelId })))
        .run();
    }
  });

  return rows.length;
}

