/**
 * Project lifecycle including the project-count quota and the cascade that archives a project's issues.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Creates a project once the plan still has room for one. The key is derived
 * from the name when the caller left it blank, so the issue numbering scheme
 * (`TF-12`) is never invented at the call site.
 *
 * The ops console duplicates a project with `projectRepo.duplicateProject`
 * plus `issueRepo.copyIssuesToProject`; those bypass the gates below.
 */
export async function createProject(
  actor: Actor,
  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.name);

  const project = await projectRepo.insertProject({
    ...input,
    slug,
    key: input.key || projectKeyFromName(input.name),
  });

  await emit("project.created", {
    ...actorEnvelope(actor),
    projectId: project.id,
    name: project.name,
    slug: project.slug,
  });

  return project;
}

/**
 * Clones a project per ADR 0012: the copy keeps the source's description,
 * visibility, colour and lead, but the name, slug and key the caller chose,
 * and starts active with no dates. Gated like a creation (project quota) plus
 * a batch check of the whole issue copy against the per-project issue quota,
 * so the clone is all-or-nothing — if the issues would not fit, nothing is
 * written, not even the project.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const issuesToCopy = input.includeIssues
    ? await issueRepo.countIssues(input.orgId, input.projectId)
    : 0;

  if (
    issuesToCopy > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, issuesToCopy)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more than ${issuesToCopy} issues in a cloned project`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const issuesCopied = input.includeIssues
    ? await issueRepo.copyLiveIssuesForClone(
        input.orgId,
        source.id,
        project.id,
        actor.userId,
      )
    : 0;

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

export async function updateProject(
  actor: Actor,
  input: UpdateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
